"""The probe business table: a tenant table built the way later tickets will build theirs, for tests to stand on.

`core.tests.urls_probe` serves it over HTTP. Each test module seeds its own rows.
"""

from core.audit import audit_trigger_sql
from core.rls import tenant_policy_sql


def create_probe_note(cursor, audit=False):
    """Create `probe_note` with the standard tenant policy, and the audit trigger when `audit` is set."""
    cursor.execute(
        "CREATE TABLE probe_note (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "
        "company_id bigint NOT NULL REFERENCES core_company(id), body text NOT NULL)"
    )
    statements = tenant_policy_sql("probe_note")
    if audit:
        statements = [*statements, *audit_trigger_sql("probe_note")]
    for statement in statements:
        cursor.execute(statement)
